void fob_ctrl_tbp_start( void )
{
	timeout_stop( fob_ctrl_vars.timeout_tbp );
	
	ATOMIC(fob_ctrl_vars.tbp_expired = FALSE);

	timeout_start( fob_ctrl_vars.timeout_tbp );
}

